// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);

        uint256 before = address(c).balance;

        vm.prank(address(this));
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok && amount > 0) {
            assertTrue(address(c).balance < before);
        } else {
            assertTrue(address(c).balance <= before);
        }
    }
}
